<script setup lang="ts">
import { ref } from 'vue'
import { command } from '../api'
interface Event { title: string; starts_at: string; ends_at: string; location?: string }
interface Transfer { from_member_id: string; to_member_id: string; amount: string }
const timetable = ref('2026-09-01 08:00-09:40 高等数学 @ A101\n2026-09-01 14:00-15:40 数据结构 @ B202')
const events = ref<Event[]>([]); const parseMessage = ref(''); const amount = ref('36.00'); const payer = ref('我'); const members = ref('我, 小林, 小周'); const transfers = ref<Transfer[]>([]); const suggestion = ref(''); const observation = ref('阳台物品暂未归位'); const loading = ref(false); const error = ref('')
async function importTimetable() { loading.value = true; try { const result = await command('dormitory', 'parse_text_timetable', timetable.value); events.value = result.data.events as Event[]; parseMessage.value = result.message } catch (error) { parseMessage.value = error instanceof Error ? error.message : '解析失败' } finally { loading.value = false } }
async function settle() { const participant_ids = members.value.split(/[,，]/).map((item) => item.trim()).filter(Boolean); if (Number(amount.value) <= 0 || participant_ids.length < 2 || !participant_ids.includes(payer.value.trim())) { error.value = '请填写有效金额，并确保付款人在参与成员中'; return } loading.value = true; error.value = ''; try { const result = await command('dormitory', 'settle_expenses', '', { expenses: [{ description: '宿舍公用支出', amount: amount.value, payer_id: payer.value, participant_ids }] }); transfers.value = result.data.transfers as Transfer[] } catch (reason) { error.value = reason instanceof Error ? reason.message : '分摊失败' } finally { loading.value = false } }
async function improve() { if (!observation.value.trim()) { error.value = '请填写观察到的情况'; return } try { const result = await command('dormitory', 'improvement_suggestion', '', { inspection: { dormitory_label: '本宿舍', observations: [observation.value], strengths: ['共同维护的意识'] } }); suggestion.value = String(result.data.suggestion ?? result.message) } catch (reason) { error.value = reason instanceof Error ? reason.message : '生成失败' } }
</script>
<template>
  <section class="dorm-page"><header class="dorm-head"><div><p class="eyebrow">生活协同 / 宿舍与日程</p><h1>课表、账目、<em>值日安排。</em></h1></div><p>所有建议只生成草案，调班与转账仍由成员确认。</p></header><p v-if="error" class="inline-error page-error">{{ error }}</p>
    <div class="dorm-grid"><article class="timetable-panel"><p class="micro">01 / 课表与行程</p><textarea v-model="timetable" class="schedule-input" aria-label="文本课表"></textarea><div class="panel-action"><span>{{ parseMessage }}</span><button class="ink-button" :disabled="loading" @click="importTimetable">导入日程</button></div><div v-if="events.length" class="event-list"><div v-for="event in events" :key="`${event.title}${event.starts_at}`" class="event-row"><time>{{ new Date(event.starts_at).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</time><b>{{ event.title }}</b><span>{{ event.location || '地点待定' }}</span></div></div></article>
      <article class="split-panel"><p class="micro">02 / 公用记账</p><h2>按分计算，生成清晰的转账建议。</h2><label>金额<input v-model="amount" inputmode="decimal" /></label><label>付款人<input v-model="payer" /></label><label>参与成员<input v-model="members" /></label><button class="ink-button" :disabled="loading" @click="settle">计算 AA 分摊</button><ul v-if="transfers.length" class="transfer-list"><li v-for="transfer in transfers" :key="`${transfer.from_member_id}${transfer.to_member_id}`">{{ transfer.from_member_id }} <span>→</span> {{ transfer.to_member_id }} <strong>¥{{ transfer.amount }}</strong></li></ul><p v-else class="empty-state">填写金额和成员后计算。</p></article>
      <article class="suggestion-panel"><p class="micro">03 / 整改建议</p><h2>把检查记录改写为可执行建议。</h2><label>观察到的情况<input v-model="observation" /></label><button class="soft-button" @click="improve">生成建议</button><p v-if="suggestion" class="suggestion-copy">{{ suggestion }}</p></article></div>
  </section>
</template>
